// Get the authentication token
const tokenRaw = $('Authenticate').first().json.data || $('Authenticate').first().json;
let token = typeof tokenRaw === 'string' ? tokenRaw : JSON.stringify(tokenRaw);
token = token.replace(/^"|"$/g, '');

// Calculate yesterday's date in ISO 8601 format
const yesterday = new Date();
yesterday.setDate(yesterday.getDate() - 1);
yesterday.setHours(0, 0, 0, 0);
const yesterdayISO = yesterday.toISOString().split('T')[0] + 'T00:00:00Z';

return [{
  json: {
    token: token,
    yesterdayDate: yesterdayISO
  }
}];

// Get orders from the OData response
const response = $('Get Orders').first().json;
const orders = response.value || [];

// Calculate today's date for the report title
const today = new Date();
const reportDate = today.toISOString().split('T')[0];

// Calculate summary
let totalAmount = 0;
let orderCount = orders.length;

// Build HTML table rows
let tableRows = '';
for (const order of orders) {
  const customerName = order.Customer ? order.Customer.Name : 'N/A';
  const orderDate = new Date(order.OrderDate).toLocaleDateString('en-US');

  // Calculate order total from items if available, otherwise use 0
  let orderTotal = 0;
  if (order.OrderItems && order.OrderItems.length > 0) {
    orderTotal = order.OrderItems.reduce((sum, item) => {
      return sum + (item.Quantity * item.UnitPrice);
    }, 0);
  }
  totalAmount += orderTotal;

  tableRows += `<tr>
    <td style="padding: 8px; border: 1px solid #ddd;">${order.OrderNumber || 'N/A'}</td>
    <td style="padding: 8px; border: 1px solid #ddd;">${customerName}</td>
    <td style="padding: 8px; border: 1px solid #ddd;">${orderDate}</td>
    <td style="padding: 8px; border: 1px solid #ddd;">${order.Status || 'N/A'}</td>
    <td style="padding: 8px; border: 1px solid #ddd; text-align: right;">$${orderTotal.toFixed(2)}</td>
  </tr>`;
}

// Build summary row
const summaryRow = `<tr style="background-color: #f0f0f0; font-weight: bold;">
  <td style="padding: 8px; border: 1px solid #ddd;" colspan="3">Total</td>
  <td style="padding: 8px; border: 1px solid #ddd;">${orderCount} order(s)</td>
  <td style="padding: 8px; border: 1px solid #ddd; text-align: right;">$${totalAmount.toFixed(2)}</td>
</tr>`;

// Build full HTML email body
const htmlBody = `
<html>
<body style="font-family: Arial, sans-serif; color: #333;">
  <h2>Daily Orders Report - ${reportDate}</h2>
  <p>Below is a summary of orders received since yesterday.</p>

  ${orderCount === 0 ? '<p><em>No orders found for this period.</em></p>' : `
  <table style="border-collapse: collapse; width: 100%; max-width: 800px;">
    <thead>
      <tr style="background-color: #4472C4; color: white;">
        <th style="padding: 8px; border: 1px solid #ddd; text-align: left;">Order #</th>
        <th style="padding: 8px; border: 1px solid #ddd; text-align: left;">Customer</th>
        <th style="padding: 8px; border: 1px solid #ddd; text-align: left;">Date</th>
        <th style="padding: 8px; border: 1px solid #ddd; text-align: left;">Status</th>
        <th style="padding: 8px; border: 1px solid #ddd; text-align: right;">Total</th>
      </tr>
    </thead>
    <tbody>
      ${tableRows}
      ${summaryRow}
    </tbody>
  </table>`}

  <p style="margin-top: 20px; font-size: 12px; color: #888;">This report was auto-generated by n8n CRM integration.</p>
</body>
</html>`;

return [{
  json: {
    reportDate: reportDate,
    subject: 'Daily Orders Report - ' + reportDate,
    htmlBody: htmlBody,
    orderCount: orderCount,
    totalAmount: totalAmount
  }
}];
